import React from "react";
import { Card, CardContent, Typography, Stack, IconButton, Box } from "@mui/material";
import DeleteIcon from "@mui/icons-material/Delete";
import EditIcon from "@mui/icons-material/Edit";

const EventList = ({ events, onDelete, onEdit }) => {
  return (
    <Stack spacing={2}>
      {events.map((event) => (
        <Card key={event._id}>
          <CardContent>
            <Box display="flex" justifyContent="space-between" alignItems="flex-start">
              <Box>
                <Typography variant="h6">{event.title}</Typography>
                <Typography variant="body2" color="textSecondary">📅 {event.date} • {event.category}</Typography>
                <Typography mt={1}>{event.description}</Typography>
                {event.location && <Typography variant="caption" display="block">📍 {event.location}</Typography>}
              </Box>

              <Box>
                <IconButton onClick={() => onEdit(event)} aria-label="edit"><EditIcon /></IconButton>
                <IconButton onClick={() => onDelete(event._id)} aria-label="delete"><DeleteIcon /></IconButton>
              </Box>
            </Box>
          </CardContent>
        </Card>
      ))}
    </Stack>
  );
};

export default EventList;
